class Widget {};

Widget w;
const Widget& cw = w;

// auto uses template-style deduction
auto myWidget1 = cw;       // myWidget1's type is Widget (const and & are stripped)

// decltype(auto) uses decltype's deduction rules
decltype(auto) myWidget2 = cw; // myWidget2's type is const Widget& (type is preserved)
